import React, { useState, useCallback } from "react";
import InfiniteScroll from "react-infinite-scroll-component";
import {Row, Col} from "antd";

const STYLE = {
  height: 30,
  border: "1px solid green",
  margin: 6,
  padding: 8
};

const INITIAL_ITEMS_LENGTH = 30;
const ITEMS_TO_ADD = 30;
const LOADING_DELAY = 1500;

const Scroller = ({ classes, jobs }) => {
  const [items, setItems] = useState(Array.from({ length: INITIAL_ITEMS_LENGTH }));

  const fetchMoreData = useCallback(() => {
    setTimeout(() => {
      setItems(prevItems => [...prevItems, ...Array.from({ length: ITEMS_TO_ADD })]);
    }, LOADING_DELAY);
  }, []);

  return (
    <InfiniteScroll
      dataLength={items.length}
      next={fetchMoreData}
      hasMore={true}
      loader={<h4>Loading...</h4>}
    >
      {items.map((_, index) => (
        <div style={STYLE} key={index}>
          div - #{index}
        </div>
      ))}
    </InfiniteScroll>
  );
}

export default Scroller;

